const [range,setRange]=useState(''),[removeMetadata,setRemoveMetadata]=useState(false),[query,setQuery]=useState(''),[results,setResults]=useState<{page:number;text:string}[]>([]),[stamp,setStamp]=useState('CONFIDENTIAL'),[stampType,setStampType]=useState('watermark');
