function openPanel(p:typeof panel){setPanel(p);setMobilePanel(true)}
function editOriginalText(){setSelected(null);setTool('select');openPanel('properties');requestAnimationFrame(()=>{if(textInspector.current){textInspector.current.open=true;textInspector.current.scrollIntoView({block:'nearest',behavior:'auto'})}})}
