async function newDocument(){const bytes=await blankPDF();await importPDF(new File([new Uint8Array(bytes)],'Untitled document.pdf',{type:'application/pdf'}))}
async function restore(){if(!draft)return;if(dirty&&!window.confirm('Replace current edits with the saved draft? Download first to keep both.'))return;await task('Restoring local draft',async()=>{const viewers:PDFDocumentProxy[]=[];try{for(const source of draft.sources){cancel.current?.signal.throwIfAborted();viewers.push(await loadViewer(source.bytes));}const custom=draft.fontOverride?new Uint8Array(draft.fontOverride):null;await applyPreviewFonts(custom?{sans:custom,serif:custom}:await bundledFonts(),cancel.current?.signal);cancel.current?.signal.throwIfAborted();docs.forEach(d=>void d.destroy());setSources(draft.sources);setDocs(viewers);h.reset(draft.state);setName(draft.name);setFontOverride(custom);setFontName(draft.fontName||'Bundled Noto fonts');setDirty(true);setDraft(null);setCurrent(0);setSelected(null);setResults([]);setOcrText('');setNotice('Restored from this device. Download to save a separate PDF.');}catch(error){await Promise.all(viewers.map(d=>d.destroy()));throw error}})}

